return [
    'id' => 'apple-intelligence', 'family' => 'assistants', 'after' => null, 'categories' => ['ai', 'mobile'],
    'title' => L('Apple Intelligence', 'Apple Intelligence'), 'short' => L('Apple Intelligence', 'Apple Intelligence'), 'level' => L('Base', 'Basics'),
    'desc' => L('L’AI di iPhone, iPad e Mac: Strumenti di scrittura, riassunti, immagini e Siri, privacy con l’elaborazione sul dispositivo e Private Cloud Compute, il framework Foundation Models per gli sviluppatori, l’intelligenza visiva e la Traduzione dal vivo.', 'The AI of iPhone, iPad and Mac: Writing Tools, summaries, images and Siri, privacy with on-device processing and Private Cloud Compute, the Foundation Models framework for developers, visual intelligence and Live Translation.'),
    'lessons' => [
        lesson('intro', L('Che cos’è', 'What it is'), [
            P('**Apple Intelligence** è l’insieme di funzioni AI integrate nei sistemi operativi di Apple (iOS, iPadOS, macOS) sui dispositivi compatibili, con chip abbastanza recenti. Non è un’app separata: compare dentro Mail, Note, Messaggi, Foto e nelle app di terze parti.', '**Apple Intelligence** is the set of AI features built into Apple’s operating systems (iOS, iPadOS, macOS) on compatible devices with recent enough chips. It is not a separate app: it shows up inside Mail, Notes, Messages, Photos and third-party apps.'),
            P('Si basa su un modello che gira **sul dispositivo** e, per le richieste più complesse, su modelli più grandi nei server Apple tramite **Private Cloud Compute**. È disponibile anche in italiano, anche se alcune funzioni arrivano prima in inglese. Per alcune richieste può passare, se lo autorizzi, a un assistente esterno come **ChatGPT**.', 'It relies on a model running **on the device** and, for more complex requests, on larger models on Apple’s servers through **Private Cloud Compute**. It is also available in Italian, although some features arrive in English first. For some requests it can hand off, if you allow it, to an external assistant such as **ChatGPT**.'),
        ], [
            Q('i1', L('Apple Intelligence è un’app da scaricare?', 'Is Apple Intelligence an app to download?'), [L('No, è integrata nel sistema operativo', 'No, it is built into the operating system'), L('Sì, dall’App Store', 'Yes, from the App Store'), L('È un sito web', 'It is a website'), L('È un accessorio', 'It is an accessory')], 0, L('Compare dentro le app.', 'It shows up inside apps.')),
            Q('i2', L('Dove girano i modelli di Apple Intelligence?', 'Where do Apple Intelligence models run?'), [L('Sul dispositivo e in Private Cloud Compute', 'On device and in Private Cloud Compute'), L('Solo su server di terzi', 'Only on third-party servers'), L('Solo offline', 'Only offline'), L('In un browser', 'In a browser')], 0, L('Prima il dispositivo, poi il cloud privato.', 'Device first, then the private cloud.')),
            Q('i3', L('A quale assistente esterno può passare alcune richieste, se autorizzi?', 'To which external assistant can it hand off some requests, if allowed?'), ['ChatGPT', 'Grok', 'Meta AI', 'Qwen'], 0, L('Solo con il tuo consenso.', 'Only with your consent.')),
        ], task('text', L('Spiega in una frase dove vengono elaborate le richieste di Apple Intelligence, citando il **dispositivo** e **Private Cloud Compute**.', 'Explain in one sentence where Apple Intelligence requests are processed, mentioning the **device** and **Private Cloud Compute**.'), '', [re('dispositiv|device|iPhone|telefono', L('Citi il dispositivo', 'You mention the device')), re('Private Cloud Compute', L('Citi Private Cloud Compute', 'You mention Private Cloud Compute'))], '', 'Le richieste semplici sono elaborate sul dispositivo, quelle più complesse sui server Apple con Private Cloud Compute.'), [
            dMatch(pMatch(), [[L('Sul dispositivo', 'On device'), L('Richieste semplici', 'Simple requests')], ['Private Cloud Compute', L('Richieste complesse', 'Complex requests')], ['ChatGPT', L('Facoltativo, con consenso', 'Optional, with consent')], [L('Chip recenti', 'Recent chips'), L('Requisito', 'Requirement')]], L('Dove gira l’AI di Apple.', 'Where Apple’s AI runs.')),
            dFlash(pFlash(), [[L('Apple Intelligence è disponibile in italiano', 'Apple Intelligence is available in Italian'), true], [L('Funziona su qualsiasi iPhone, anche molto vecchio', 'It works on any iPhone, even very old'), false], [L('Una parte delle richieste resta sul dispositivo', 'Some requests stay on the device'), true], [L('Manda sempre tutto a ChatGPT', 'It always sends everything to ChatGPT'), false]], L('AI integrata.', 'Built-in AI.')),
        ]),
        lesson('features', L('Funzioni di ogni giorno', 'Everyday features'), [
            P('Gli **Strumenti di scrittura** compaiono ovunque si scrive: correggere, riscrivere con un tono diverso (amichevole, professionale, conciso), riassumere, trasformare in elenco o tabella. Le **notifiche** e le email lunghe possono essere riassunte, e Mail mette in evidenza i messaggi prioritari.', '**Writing Tools** appear wherever you type: proofread, rewrite in a different tone (friendly, professional, concise), summarise, turn into a list or table. **Notifications** and long emails can be summarised, and Mail highlights priority messages.'),
            P('Altre funzioni: **Image Playground** e **Genmoji** creano immagini ed emoji personalizzate; **Ripulisci** in Foto toglie oggetti di disturbo; la ricerca in Foto capisce descrizioni in linguaggio naturale; **Siri** capisce meglio le richieste e le puoi anche scrivere, non solo dire a voce.', 'Other features: **Image Playground** and **Genmoji** create custom images and emoji; **Clean Up** in Photos removes distracting objects; Photos search understands natural-language descriptions; **Siri** understands requests better and can be typed to, not just spoken to.'),
        ], [
            Q('f1', L('Che cosa fanno gli Strumenti di scrittura?', 'What do Writing Tools do?'), [L('Correggono, riscrivono e riassumono testi', 'Proofread, rewrite and summarise text'), L('Stampano documenti', 'Print documents'), L('Inviano email da soli', 'Send email by themselves'), L('Fanno backup', 'Make backups')], 0, L('Ovunque si scrive.', 'Wherever you type.')),
            Q('f2', L('Che cosa fa Ripulisci in Foto?', 'What does Clean Up in Photos do?'), [L('Toglie oggetti di disturbo', 'Removes distracting objects'), L('Cancella foto doppie', 'Deletes duplicate photos'), L('Cambia formato', 'Changes format'), L('Aggiunge filtri vintage', 'Adds vintage filters')], 0, L('Ritocco intelligente.', 'Smart retouching.')),
            Q('f3', L('Che cos’è Genmoji?', 'What is Genmoji?'), [L('Emoji personalizzate generate', 'Generated custom emoji'), L('Un gioco', 'A game'), L('Un’app di musica', 'A music app'), L('Una tastiera fisica', 'A physical keyboard')], 0, L('Da una descrizione.', 'From a description.')),
        ], task('text', L('Indica quale funzione useresti per ciascun bisogno, uno per riga come `bisogno: funzione`. Bisogni: `rendere più professionale una mail`, `togliere un passante da una foto`.', 'Say which feature you would use for each need, one per line as `need: feature`. Needs: `make an email more professional`, `remove a passer-by from a photo`.'), '', [re('(mail|email)[^:\n]*:\s*(strumenti di scrittura|writing tools)', L('Strumenti di scrittura per la mail', 'Writing Tools for the email')), re('(foto|photo)[^:\n]*:\s*(ripulisci|clean up)', L('Ripulisci per la foto', 'Clean Up for the photo'))], '', "rendere più professionale una mail: Strumenti di scrittura\ntogliere un passante da una foto: Ripulisci"), [
            dMatch(pMatch(), [[L('Strumenti di scrittura', 'Writing Tools'), L('Correggere e riscrivere', 'Proofread and rewrite')], [L('Riassunti delle notifiche', 'Notification summaries'), L('Meno distrazioni', 'Fewer distractions')], ['Image Playground', L('Creare immagini', 'Create images')], [L('Ripulisci', 'Clean Up'), L('Togliere oggetti', 'Remove objects')], ['Siri', L('Richieste a voce o scritte', 'Spoken or typed requests')]], L('Le funzioni di Apple Intelligence.', 'Apple Intelligence features.')),
            dFlash(pFlash(), [[L('Gli Strumenti di scrittura funzionano in molte app', 'Writing Tools work in many apps'), true], [L('Siri accetta solo comandi vocali', 'Siri only accepts voice commands'), false], [L('Le email lunghe si possono riassumere', 'Long emails can be summarised'), true], [L('Ripulisci aggiunge persone alle foto', 'Clean Up adds people to photos'), false]], L('AI nelle piccole cose.', 'AI in the little things.')),
        ]),
        lesson('privacy', L('Privacy', 'Privacy'), [
            P('L’approccio di Apple è elaborare il più possibile **sul dispositivo**. Quando serve il cloud, **Private Cloud Compute** usa server con chip Apple progettati perché i dati siano usati solo per la richiesta, non conservati né accessibili ad Apple; il software di questi server è pubblicato perché ricercatori indipendenti possano verificarlo.', 'Apple’s approach is to process as much as possible **on the device**. When the cloud is needed, **Private Cloud Compute** uses Apple-silicon servers designed so data is used only for the request, not stored or accessible to Apple; these servers’ software is published so independent researchers can verify it.'),
            Fig(L(fig_appleint_where('it'), fig_appleint_where('en')),
                L('La tua richiesta va, se è più semplice, al riquadro verde «sul dispositivo», dove i dati non escono; se è più complessa, al riquadro viola Private Cloud Compute, dove i dati sono usati solo per la richiesta e non conservati. Da qui una freccia tratteggiata porta a ChatGPT, solo se attivato e dopo la tua conferma.', 'Your request goes, if it is simpler, to the green “on the device” box, where the data does not leave; if it is more complex, to the purple Private Cloud Compute box, where the data is used only for the request and not stored. From there a dashed arrow leads to ChatGPT, only if turned on and after you confirm.'),
                L('Prima il dispositivo, poi il cloud privato di Apple; un servizio esterno solo con il tuo sì.', 'Device first, then Apple’s private cloud; an outside service only with your yes.')),
            P('Se attivi l’integrazione con **ChatGPT**, il dispositivo chiede conferma prima di inviare una richiesta; senza account OpenAI collegato, Apple dichiara che le richieste non vengono conservate da OpenAI. Puoi disattivare l’integrazione nelle Impostazioni in qualsiasi momento.', 'If you enable the **ChatGPT** integration, the device asks for confirmation before sending a request; without a linked OpenAI account, Apple states requests are not stored by OpenAI. You can turn the integration off in Settings at any time.'),
        ], [
            Q('p1', L('Qual è il principio di Apple sulla privacy dell’AI?', 'What is Apple’s principle on AI privacy?'), [L('Elaborare il più possibile sul dispositivo', 'Process as much as possible on device'), L('Mandare tutto nel cloud', 'Send everything to the cloud'), L('Vendere i dati', 'Sell the data'), L('Nessuno', 'None')], 0, L('Il cloud solo quando serve.', 'Cloud only when needed.')),
            Q('p2', L('Perché il software di Private Cloud Compute è pubblicato?', 'Why is Private Cloud Compute’s software published?'), [L('Perché ricercatori indipendenti possano verificarlo', 'So independent researchers can verify it'), L('Per venderlo', 'To sell it'), L('Per errore', 'By mistake'), L('Non è pubblicato', 'It is not published')], 0, L('Trasparenza verificabile.', 'Verifiable transparency.')),
            Q('p3', L('Che cosa succede prima di inviare una richiesta a ChatGPT?', 'What happens before a request is sent to ChatGPT?'), [L('Il dispositivo chiede conferma', 'The device asks for confirmation'), L('Niente, parte da sola', 'Nothing, it goes by itself'), L('Si riavvia il telefono', 'The phone restarts'), L('Si paga', 'You pay')], 0, L('E si può disattivare.', 'And it can be turned off.')),
        ], task('text', L('Scrivi due righe con `-` che spieghino come Apple protegge la privacy: una sul **dispositivo** e una su **Private Cloud Compute**.', 'Write two lines with `-` explaining how Apple protects privacy: one about the **device** and one about **Private Cloud Compute**.'), "- \n- ", [re('^-\s*\S.{5,}\n-\s*\S.{5,}', L('Due righe', 'Two lines')), re('dispositiv|device', L('Il dispositivo', 'The device')), re('Private Cloud Compute', L('Private Cloud Compute', 'Private Cloud Compute'))], '', "- molte richieste sono elaborate direttamente sul dispositivo\n- con Private Cloud Compute i dati servono solo per la richiesta e non vengono conservati"), [
            dMatch(pMatch(), [[L('Sul dispositivo', 'On device'), L('I dati non escono', 'Data does not leave')], ['Private Cloud Compute', L('Server Apple senza conservazione', 'Apple servers without retention')], [L('Software pubblicato', 'Published software'), L('Verificabile da esperti', 'Verifiable by experts')], [L('Conferma per ChatGPT', 'ChatGPT confirmation'), L('Tu decidi ogni volta', 'You decide each time')]], L('Privacy per progetto.', 'Privacy by design.')),
            dFlash(pFlash(), [[L('L’integrazione con ChatGPT si può disattivare', 'The ChatGPT integration can be turned off'), true], [L('Private Cloud Compute conserva tutte le richieste', 'Private Cloud Compute stores all requests'), false], [L('Molte funzioni girano sul dispositivo', 'Many features run on device'), true], [L('Apple vende le richieste agli inserzionisti', 'Apple sells requests to advertisers'), false]], L('Dati protetti.', 'Protected data.')),
        ]),
        lesson('developers', L('Per gli sviluppatori', 'For developers'), [
            P('Con il framework **Foundation Models** le app possono usare il modello di Apple Intelligence **sul dispositivo** direttamente da Swift: niente costi per token, funziona offline e i dati restano sul dispositivo. È adatto a riassunti, estrazione di informazioni, suggerimenti e piccoli testi.', 'With the **Foundation Models** framework apps can use the Apple Intelligence **on-device** model directly from Swift: no per-token costs, it works offline and data stays on the device. It suits summaries, information extraction, suggestions and short texts.'),
            C('import FoundationModels

let sessione = LanguageModelSession(instructions: "Rispondi in italiano, in una frase.")
let risposta = try await sessione.respond(to: "Suggerisci un titolo per una nota sulla spesa.")
print(risposta.content)', 'swift'),
            P('Il modello sul dispositivo è piccolo: ottimo per compiti mirati, non per ragionamenti lunghi o conoscenza enciclopedica. Controlla sempre che sia disponibile sul dispositivo dell’utente e prevedi un comportamento alternativo quando non lo è.', 'The on-device model is small: great for focused tasks, not for long reasoning or encyclopaedic knowledge. Always check it is available on the user’s device and plan a fallback when it is not.'),
            Fig(L(fig_appleint_fallback('it'), fig_appleint_fallback('en')),
                L('La tua app arriva a un rombo «modello disponibile?». Se sì, usa il modello sul dispositivo, offline e senza costi a token; se no, passa a un’alternativa: nascondere la funzione o usare un’altra strada. Sotto: disponibile vuol dire dispositivo compatibile, funzione attiva, modello pronto.', 'Your app reaches a diamond “model available?”. If yes, it uses the on-device model, offline and with no per-token cost; if no, it switches to a fallback: hide the feature or take another route. Below: available means a compatible device, the feature on and the model ready.'),
                L('Controlla sempre la disponibilità prima di chiamare il modello.', 'Always check availability before calling the model.')),
        ], [
            Q('d1', L('Quale framework dà accesso al modello sul dispositivo?', 'Which framework gives access to the on-device model?'), ['Foundation Models', 'UIKit', 'CoreData', 'MapKit'], 0, L('Da Swift.', 'From Swift.')),
            Q('d2', L('Qual è un vantaggio del modello sul dispositivo?', 'What is an advantage of the on-device model?'), [L('Funziona offline e senza costi per token', 'Works offline with no per-token costs'), L('È il modello più grande al mondo', 'It is the world’s largest model'), L('Conosce tutte le notizie di oggi', 'It knows all of today’s news'), L('Funziona su Android', 'It works on Android')], 0, L('E i dati restano lì.', 'And data stays there.')),
            Q('d3', L('Per quali compiti è adatto?', 'Which tasks does it suit?'), [L('Compiti mirati come riassunti ed estrazione', 'Focused tasks like summaries and extraction'), L('Ricerche enciclopediche', 'Encyclopaedic research'), L('Ragionamenti lunghissimi', 'Very long reasoning'), L('Generare video', 'Generating video')], 0, L('È un modello piccolo.', 'It is a small model.')),
        ], task('swift', L('Crea una `LanguageModelSession` e chiedi con `respond(to:)` di `"Riassumi in una frase: …"`, poi stampa `content`.', 'Create a `LanguageModelSession` and ask with `respond(to:)` to `"Riassumi in una frase: …"`, then print `content`.'), "import FoundationModels\n", [re('let\s+\w+\s*=\s*LanguageModelSession\s*\(', L('La sessione', 'The session')), re('try\s+await\s+\w+\.respond\s*\(\s*to\s*:\s*"Riassumi in una frase', L('La richiesta', 'The request')), re('print\s*\(\s*\w+\.content\s*\)', L('Stampi la risposta', 'You print the answer'))], '', "let sessione = LanguageModelSession()\nlet risposta = try await sessione.respond(to: \"Riassumi in una frase: oggi riunione alle 10 sul budget.\")\nprint(risposta.content)"), [
            dOrder(pSort(), ['import FoundationModels', 'let sessione = LanguageModelSession()', 'let risposta = try await sessione.respond(to: "Ciao")', 'print(risposta.content)'], L('Importa, crea, chiedi, stampa.', 'Import, create, ask, print.')),
            dMatch(pMatch(), [['FoundationModels', L('Il framework', 'The framework')], ['LanguageModelSession', L('Una conversazione', 'A conversation')], ['respond(to:)', L('Invia la richiesta', 'Sends the request')], [L('Sul dispositivo', 'On device'), L('Offline, niente costi a token', 'Offline, no token costs')]], L('L’AI di Apple nelle tue app.', 'Apple’s AI in your apps.')),
        ]),
        lesson('limits', L('Requisiti, lingue e buon uso', 'Requirements, languages and good use'), [
            P('Apple Intelligence funziona solo sui dispositivi più recenti (per l’iPhone, dalla serie **15 Pro** in poi; Mac e iPad con chip **M1** o successivi) e va attivata nelle impostazioni. L’italiano è tra le lingue supportate, ma le funzioni più nuove spesso arrivano prima in inglese e in alcuni paesi: la nuova **Siri AI**, per esempio, è partita in poche lingue e, per le regole europee sui mercati digitali, inizialmente non su iPhone e iPad nell’Unione Europea. Alcune funzioni hanno anche limiti di uso giornalieri.', 'Apple Intelligence works only on recent devices (for iPhone, from the **15 Pro** series onwards; Macs and iPads with an **M1** chip or later) and must be turned on in the settings. Italian is among the supported languages, but the newest features often arrive first in English and in some countries: the new **Siri AI**, for example, launched in a few languages and, because of EU digital markets rules, initially not on iPhone and iPad in the European Union. Some features also have daily usage limits.'),
            P('Gli **Strumenti di scrittura** correggono e riformulano, ma possono cambiare il senso di una frase: rileggi prima di inviare. I **riassunti delle notifiche** sono comodi ma a volte sbagliano: per le notizie e i messaggi importanti apri l’originale.', '**Writing Tools** correct and rephrase, but they can change a sentence’s meaning: reread before sending. **Notification summaries** are handy but sometimes wrong: for news and important messages open the original.'),
        ], [
            Q('li1', L('Quali iPhone supportano Apple Intelligence?', 'Which iPhones support Apple Intelligence?'), [L('Dalla serie 15 Pro in poi', 'From the 15 Pro series onwards'), L('Tutti gli iPhone', 'All iPhones'), L('Solo l’iPhone 11', 'Only iPhone 11'), L('Nessuno', 'None')], 0, L('Servono memoria e chip recenti.', 'Recent chips and memory are needed.')),
            Q('li2', L('Che cosa fai con un riassunto di notifica importante?', 'What do you do with an important notification summary?'), [L('Apri il messaggio originale', 'Open the original message'), L('Ti fidi ciecamente', 'Trust it blindly'), L('Lo cancelli', 'Delete it'), L('Lo inoltri', 'Forward it')], 0, L('I riassunti possono sbagliare.', 'Summaries can be wrong.')),
            Q('li3', L('Perché rileggere un testo riformulato?', 'Why reread a rephrased text?'), [L('Può aver cambiato il senso', 'It may have changed the meaning'), L('Cambia la lingua', 'It changes the language'), L('Toglie la firma', 'It removes the signature'), L('Non serve', 'It is not needed')], 0, L('Il messaggio resta tuo.', 'The message is still yours.')),
        ], task('text', L('Scrivi due regole d’uso, una per riga con `-`: una sugli strumenti di scrittura, una sui riassunti.', 'Write two usage rules, one per line with `-`: one on writing tools, one on summaries.'), '', [re('^-.*(scrittur|writing|riformul|rephras|rilegg|reread)', L('Regola sulla scrittura', 'Rule on writing')), re('^-.*(riassunt|summar|notific|originale|original)', L('Regola sui riassunti', 'Rule on summaries'))], '', "- Rileggo sempre il testo riformulato dagli strumenti di scrittura\n- Per i messaggi importanti apro l’originale invece del riassunto"), [
            dMatch(pMatch(), [['iPhone 15 Pro', L('Requisito minimo', 'Minimum requirement')], ['M1', L('Chip per Mac e iPad', 'Chip for Mac and iPad')], [L('Strumenti di scrittura', 'Writing Tools'), L('Correggono e riformulano', 'Correct and rephrase')], [L('Riassunti', 'Summaries'), L('Comodi ma fallibili', 'Handy but fallible')]], L('Usarla bene.', 'Using it well.')),
            dFlash(pFlash(), [[L('Apple Intelligence va attivata nelle impostazioni', 'Apple Intelligence must be turned on in settings'), true], [L('Funziona su tutti gli iPhone', 'It works on every iPhone'), false], [L('I riassunti delle notifiche possono sbagliare', 'Notification summaries can be wrong'), true], [L('L’italiano non è supportato', 'Italian is not supported'), false]], L('Limiti e buone abitudini.', 'Limits and good habits.')),
        ]),
        lesson('visual-translate', L('Intelligenza visiva e Traduzione dal vivo', 'Visual intelligence and Live Translation'), [
            P('Con l’**intelligenza visiva** inquadri qualcosa con la fotocamera e chiedi: che pianta è, che orari ha questo negozio, che cosa dice questo cartello. Funziona anche su ciò che hai sullo **schermo**: da uno screenshot puoi cercare un oggetto simile, farti spiegare un grafico o aggiungere al Calendario la data di un evento.', 'With **visual intelligence** you point the camera at something and ask: what plant it is, what this shop’s opening hours are, what this sign says. It also works on what is on your **screen**: from a screenshot you can search for a similar item, have a chart explained or add an event’s date to Calendar.'),
            P('La **Traduzione dal vivo** traduce mentre comunichi: i messaggi in Messaggi, i sottotitoli in FaceTime, la voce durante le telefonate e, con gli AirPods compatibili, ciò che ti dice una persona di fronte a te. Gran parte del lavoro avviene sul dispositivo. Le lingue e i paesi disponibili cambiano da funzione a funzione: controlla nelle Impostazioni.', '**Live Translation** translates as you communicate: messages in Messages, captions in FaceTime, the voice during phone calls and, with compatible AirPods, what a person in front of you is saying. Most of the work happens on the device. The available languages and countries vary from feature to feature: check in Settings.'),
            Tip('Una traduzione automatica può sbagliare un nome, un numero o un tono: per un contratto, una visita medica o una pratica ufficiale serve un interprete o una verifica umana.', 'An automatic translation can get a name, a number or a tone wrong: for a contract, a medical visit or an official procedure you need an interpreter or a human check.'),
        ], [
            Q('vt1', L('Su che cosa funziona l’intelligenza visiva, oltre alla fotocamera?', 'What does visual intelligence work on, besides the camera?'), [L('Sulle chiamate vocali', 'On voice calls'), L('Sulla cronologia di Safari', 'On Safari history'), L('Sui contenuti dello schermo, da uno screenshot', 'On screen content, from a screenshot'), L('Sui file di altri utenti', 'On other users’ files')], 2, L('Spiega, cerca, aggiunge eventi.', 'It explains, searches, adds events.')),
            Q('vt2', L('Dove può tradurre la Traduzione dal vivo?', 'Where can Live Translation translate?'), [L('In Messaggi, FaceTime, telefonate e con gli AirPods', 'In Messages, FaceTime, calls and with AirPods'), L('Solo nei siti web in Safari', 'Only on websites in Safari'), L('Solo nei documenti Pages', 'Only in Pages documents'), L('Solo nelle email in inglese', 'Only in English emails')], 0, L('Mentre comunichi.', 'While you communicate.')),
            Q('vt3', L('Per una visita medica in un’altra lingua, che cosa conviene?', 'For a medical visit in another language, what is advisable?'), [L('Fidarsi sempre della traduzione automatica', 'Always trust the automatic translation'), L('Spegnere il telefono', 'Turn off the phone'), L('Tradurre solo le parole difficili', 'Translate only the hard words'), L('Un interprete o una verifica umana', 'An interpreter or a human check')], 3, L('Gli errori lì costano cari.', 'Mistakes there are costly.')),
        ], task('text', L('Indica quale funzione useresti per ciascun bisogno, uno per riga come `bisogno: funzione`. Bisogni: `capire che pianta ho davanti`, `parlare al telefono con un albergo spagnolo`.', 'Say which feature you would use for each need, one per line as `need: feature`. Needs: `find out what plant is in front of me`, `talk on the phone with a Spanish hotel`.'), '', [re('(pianta|plant)[^:\n]*:\s*(intelligenza visiva|visual intelligence)', L('Intelligenza visiva per la pianta', 'Visual intelligence for the plant')), re('(telefono|albergo|phone|hotel)[^:\n]*:\s*(traduzione dal vivo|live translation)', L('Traduzione dal vivo per la telefonata', 'Live Translation for the call'))], '', "capire che pianta ho davanti: intelligenza visiva\nparlare al telefono con un albergo spagnolo: Traduzione dal vivo"), [
            dMatch(pMatch(), [[L('Intelligenza visiva', 'Visual intelligence'), L('Domande su ciò che inquadri', 'Questions about what you frame')], [L('Screenshot', 'Screenshot'), L('Domande su ciò che è sullo schermo', 'Questions about what is on screen')], [L('Traduzione dal vivo', 'Live Translation'), L('Messaggi, chiamate e FaceTime', 'Messages, calls and FaceTime')], ['AirPods', L('Traduzione di chi ti parla di persona', 'Translating who speaks to you in person')]], L('Vedere e capire.', 'Seeing and understanding.')),
            dFlash(pFlash(), [[L('L’intelligenza visiva può aggiungere un evento al Calendario', 'Visual intelligence can add an event to Calendar'), true], [L('La traduzione automatica non sbaglia mai i numeri', 'Automatic translation never gets numbers wrong'), false], [L('Le lingue disponibili variano da funzione a funzione', 'Available languages vary from feature to feature'), true], [L('La Traduzione dal vivo funziona solo in Safari', 'Live Translation only works in Safari'), false]], L('Il mondo, tradotto.', 'The world, translated.')),
        ]),
    ],
